12	describe('ToolRegistry inputSchema validation acceptance', () => {
13	  afterEach(() => {
14	    setLogger(undefined);
15	  });
16	
17	  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
18	    const registry = new ToolRegistry();
19	    const executorCalls = registerLocationTool(registry);
20	
21	    const response = await registry.execute('get_weather', {});
22	
23	    expect({
24	      executorCalls: executorCalls(),
25	      mentionsRequiredField: response.result.includes('location') && /required/i.test(response.result),
26	    }).toEqual({
27	      executorCalls: 0,
28	      mentionsRequiredField: true,
29	    });
30	  });
31	
32	  it('rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs', async () => {
33	    const recordedLogs: string[] = [];
34	    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
35	      recordedLogs.push(JSON.stringify({category, message, fields}));
36	    };
37	    const logger: Logger = {
38	      debug: recordLine,
39	      info: recordLine,
40	      warn: recordLine,
41	      error: recordLine,
42	    };
43	    setLogger(logger);
44	
45	    const registry = new ToolRegistry();
46	    let executorCalls = 0;
47	    registry.register(
48	      {
49	        name: 'ssn_lookup',
50	        description: 'Look up record by identifier',
51	        inputSchema: {
52	          type: 'object',
53	          properties: {ssn: {type: 'string'}},
54	          required: ['ssn'],
55	        },
56	      },
57	      async () => {
58	        executorCalls += 1;
59	        return 'found';
60	      }
61	    );
62	
63	    const response = await registry.execute('ssn_lookup', {ssn: 123456789});
64	
65	    expect({
66	      executorCalls,
67	      mentionsField: response.result.includes('ssn'),
68	      mentionsExpectedType: response.result.includes('string'),
69	      leaksValueInResult: response.result.includes('123456789'),
70	      leaksValueInLogs: recordedLogs.some(line => line.includes('123456789')),
71	    }).toEqual({
72	      executorCalls: 0,
73	      mentionsField: true,
74	      mentionsExpectedType: true,
75	      leaksValueInResult: false,
76	      leaksValueInLogs: false,
77	    });
78	  });
79	
80	  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
81	    const registry = new ToolRegistry();
82	
83	    expect(() =>
84	      registry.register(
85	        {
86	          name: 'broken_weather',
87	          description: 'Has an invalid JSON Schema type',
88	          inputSchema: {
89	            type: 'object',
90	            properties: {location: {type: 'not-a-json-schema-type'}},
91	          },
92	        },
93	        async () => 'unreachable'
94	      )
95	    ).toThrow(/broken_weather/);
96	  });
97	
98	  it('returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round', async () => {
99	    const registry = new ToolRegistry();
100	    const executorInputs: Array<Record<string, unknown>> = [];
101	    registry.register(
102	      () => ({
103	        name: 'get_weather',
104	        description: 'Get weather for a location',
105	        inputSchema: {
106	          type: 'object',
107	          properties: {location: {type: 'string'}},
108	          required: ['location'],
109	        },
110	      }),
111	      async input => {
112	        executorInputs.push(input);
113	        return `22C in ${String(input.location)}`;
114	      }
115	    );
116	
