// Reads the CI pod's coverage-final.json (the red run's own data) and replicates
// jest's coverageThreshold grouping (see @jest/reporters build/index.js _checkThreshold):
// a file counts toward EVERY path-prefix group it matches; only files matching no
// non-global group fall into `global`.
const path = require('path');
const libCoverage = require('/var/tmp/loop-bench/runs/79d6e7933ca1/workspace/target/node_modules/istanbul-lib-coverage');

const file = process.argv[2];
const data = require(file);
const map = libCoverage.createCoverageMap(data);

const thresholds = {
  'src/orchestration/': {statements: 88.3, branches: 80.85, functions: 92, lines: 87.91},
  'src/orchestration/tools/': {statements: 66.66, branches: 56.25, functions: 71.42, lines: 70.83},
  'src/infrastructure/stores/': {statements: 100, branches: 100, functions: 100, lines: 100},
  'src/providers/vertex/': {statements: 87.95, branches: 74.64, functions: 93.33, lines: 91.78},
  'src/providers/mock/': {statements: 100, branches: 78.57, functions: 100, lines: 100},
  global: {statements: 71.48, branches: 64.82, functions: 68.57, lines: 71.9},
};

const root = '/var/tmp/loop-bench/runs/79d6e7933ca1/ci-4/';
const coveredFiles = map.files().map(f => f.replace(root, '/'));

const groups = {};
for (const f of coveredFiles) {
  const matches = Object.keys(thresholds).filter(
    g => g !== 'global' && f.indexOf(g) === 0
  );
  if (matches.length === 0) matches.push('global');
  for (const g of matches) (groups[g] = groups[g] || []).push(f);
}

for (const [group, files] of Object.entries(groups)) {
  let combined;
  for (const f of files) {
    const summary = map.fileCoverageFor(root + f).toSummary();
    combined = combined ? combined.merge(summary) : summary;
  }
  const t = thresholds[group];
  const row = ['statements', 'branches', 'functions', 'lines']
    .map(k => {
      const pct = combined[k].pct;
      const flag = pct < t[k] ? ' **BELOW**' : '';
      return `${k} ${pct}${flag} (floor ${t[k]})`;
    })
    .join(', ');
  console.log(`${group} [${files.length} files]: ${row}`);
}

